model_safe_stan:
data {
  int<lower=0> N; // observations (Full MNIST: 60K)
  int<lower=0> M; // predictors   (MNIST: 784)
  matrix[N, M] x; // data matrix  (Full MNIST: 60K x 784 = 47M)
  int<lower=2> K; // number of categories (MNIST: 10)
  array[N] int<lower=1, upper=K> y; // categories
}
transformed data {
  int<lower=1> J = 100; // number of hidden units (e.g. 100)

  // prior parametrization in Lampinen and Vehtari (2001)
  real nu_alpha = 0.5;
  real s2_0_alpha = (0.05 / M ^ (1 / nu_alpha)) ^ 2;
  real nu_beta = 0.5;
  real s2_0_beta = (0.05 / J ^ (1 / nu_beta)) ^ 2;

  vector[N] ones = rep_vector(1, N);
  matrix[N, M + 1] x1 = append_col(ones, x);
}
parameters {
  real<lower=0> sigma2_alpha;
  real<lower=0> sigma2_beta;
  vector[M * J] alpha_vec;
  vector[J * (K - 1)] beta_vec;
  row_vector[J] alpha1;
  row_vector[K - 1] beta1;
}
transformed parameters {
  matrix[M, J] alpha = to_matrix(alpha_vec, M, J);
  matrix[J, K - 1] beta = to_matrix(beta_vec, J, K - 1);
}
model {
  // Priors
  alpha1 ~ normal(0, 1);
  beta1 ~ normal(0, 1);
  sigma2_alpha ~ inv_gamma(nu_alpha / 2, nu_alpha * s2_0_alpha / 2);
  sigma2_beta ~ inv_gamma(nu_beta / 2, nu_beta * s2_0_beta / 2);
  alpha_vec ~ normal(0, sqrt(sigma2_alpha));
  beta_vec ~ normal(0, sqrt(sigma2_beta));

  {
    matrix[N, J] h = tanh(x1 * append_row(alpha1, alpha));
    vector[K] alpha_glm;
    matrix[J, K] beta_glm;

    alpha_glm[1] = 1;
    alpha_glm[2 : K] = beta1';
    beta_glm[ : , 1] = rep_vector(0, J);
    beta_glm[ : , 2 : K] = beta;

    y ~ categorical_logit_glm(h, alpha_glm, beta_glm);
  }
}
